* { box-sizing: border-box; }
body { margin: 12px; color: #17202a; background: #fff; font: 16px/1.35 sans-serif; }
main { max-width: 720px; }
h1 { font-size: 24px; } h2 { font-size: 20px; }
p { margin: 10px 0; } a { color: #0645ad; }
figure { margin: 12px 0; padding: 8px; border: 1px solid #85929e; }
figcaption { margin-top: 6px; }
.flow figure { float: right; width: 220px; margin-left: 12px; }
.flow::after { content: ""; display: block; clear: both; }
img { display: block; width: 160px; height: 80px; image-rendering: auto; }
.nested { margin: 8px 0; padding: 6px; background: #edf4f8; }
.nested img { width: 96px; height: 48px; }
.grid { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); gap: 12px; margin: 16px 0; }
.boxless { display: contents; }
.main { grid-column: 1; grid-row: 1 / span 2; background: #eef4e8; padding: 8px; }
.aside { grid-column: 2; grid-row: 1; background: #fff3d9; padding: 8px; }
.tail { grid-column: 2; grid-row: 2; background: #f6eaf7; padding: 8px; }
.inner { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 8px; }
.inner-a { grid-column: 1; grid-row: 1; border: 1px solid #455; padding: 6px; }
.inner-b { grid-column: 2; grid-row: 1; border: 1px solid #455; padding: 6px; }
.long { overflow-wrap: anywhere; }
.destinations { border-top: 1px solid #85929e; margin-top: 20px; }
